// ═══ PROCESS vs THREAD comparison ═══
//
// Feature          Process                    Thread
// Memory           Own address space           Shares process heap; own stack
// Creation cost    Heavy (~100ms, ~100MB)      Light (~1ms, ~1MB stack)
// Communication    IPC (pipes, sockets) slow   Shared memory (fast)
// Isolation        Crash-safe (others survive)  One crash kills all threads
// Context switch   Expensive (TLB flush)        Cheap (same address space)
// Max count        Hundreds                     Thousands
// Use case         Microservices, isolation      Concurrent tasks within app

// ═══ CREATING A PROCESS in Java ═══
ProcessBuilder pb = new ProcessBuilder("java", "-jar", "settlement-service.jar");
Process process = pb.start();  // NEW OS process — own memory, own JVM!
// Communication: process.getInputStream() / getOutputStream() (slow)

// ═══ CREATING A THREAD in Java ═══
Thread thread = new Thread(() -> {
    // This runs in a NEW thread but SAME process
    // Shares heap memory with main thread!
    System.out.println("Balance: " + sharedBalance);  // can access shared data
});
thread.start();  // OS creates a new thread (~1ms, ~1MB stack)

// ═══ SHARED MEMORY PROBLEM ═══
// Two threads modifying the same variable WITHOUT synchronization:
int balance = 100000;
// Thread-1: balance = balance - 50000;  → reads 100000, computes 50000
// Thread-2: balance = balance - 30000;  → reads 100000, computes 70000
// Thread-1 writes 50000. Thread-2 writes 70000.
// Expected: 20000. Actual: 70000 or 50000! RACE CONDITION!
// FIX: synchronized, Lock, AtomicInteger

// ═══ THREAD STACK vs PROCESS HEAP ═══
// Heap: shared by ALL threads — objects, arrays, class instances
// Stack: per-thread — local variables, method call frames, return addresses
// Stack size: default ~1MB per thread (-Xss to adjust)
// 1000 threads × 1MB stack = 1GB just for stacks!
