// ─── File: src/test/java/com/bank/threading/ProcessVsThreadTest.java ───
package com.bank.threading;

import org.junit.jupiter.api.Test;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.CountDownLatch;
import static org.assertj.core.api.Assertions.*;

class ProcessVsThreadTest {

    // ═══ Threads SHARE heap memory ═══
    @Test
    void threads_shareHeapMemory() throws InterruptedException {
        AtomicInteger sharedCounter = new AtomicInteger(0);
        int threadCount = 10;
        CountDownLatch latch = new CountDownLatch(threadCount);

        for (int i = 0; i < threadCount; i++) {
            new Thread(() -> {
                sharedCounter.incrementAndGet();  // ALL threads access SAME counter!
                latch.countDown();
            }).start();
        }

        latch.await();
        assertThat(sharedCounter.get()).isEqualTo(10);  // shared memory!
    }

    // ═══ Each thread has OWN stack ═══
    @Test
    void threads_ownStack() throws InterruptedException {
        int[] results = new int[2];
        Thread t1 = new Thread(() -> {
            int localVar = 100;  // on T1's stack — invisible to T2!
            results[0] = localVar;
        });
        Thread t2 = new Thread(() -> {
            int localVar = 200;  // on T2's stack — different from T1's!
            results[1] = localVar;
        });

        t1.start(); t2.start();
        t1.join(); t2.join();
        assertThat(results[0]).isEqualTo(100);
        assertThat(results[1]).isEqualTo(200);  // each thread had its own localVar!
    }

    // ═══ Race condition without synchronization ═══
    @Test
    void raceCondition_withoutSync() throws InterruptedException {
        int[] balance = {100000};  // shared mutable state!
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                balance[0] -= 1000;  // NOT atomic! Read-modify-write race!
                latch.countDown();
            }).start();
        }

        latch.await();
        // Expected: 0. Actual: might be > 0 due to race condition!
        // Some decrements are LOST because threads read stale values.
        System.out.println("Balance after race: " + balance[0]);
    }

    // ═══ Fixed with AtomicInteger ═══
    @Test
    void fixedWithAtomic() throws InterruptedException {
        AtomicInteger balance = new AtomicInteger(100000);
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                balance.addAndGet(-1000);  // ATOMIC! No race!
                latch.countDown();
            }).start();
        }

        latch.await();
        assertThat(balance.get()).isEqualTo(0);  // exactly 0!
    }
}
